import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.76ZGnlPi.js";const u=JSON.parse('{"title":"R2 Lifecycle Rule: Temp Manifest Attachments","description":"","frontmatter":{},"headers":[],"relativePath":"admin/custom-booking/r2-wa-manifest-lifecycle.md","filePath":"admin/custom-booking/r2-wa-manifest-lifecycle.md"}'),r={name:"admin/custom-booking/r2-wa-manifest-lifecycle.md"};function l(s,e,n,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="r2-lifecycle-rule-temp-manifest-attachments" tabindex="-1">R2 Lifecycle Rule: Temp Manifest Attachments <a class="header-anchor" href="#r2-lifecycle-rule-temp-manifest-attachments" aria-label="Permalink to &quot;R2 Lifecycle Rule: Temp Manifest Attachments&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The admin WhatsApp notification for custom bookings attaches a generated Excel manifest. To avoid storing large base64 blobs in BullMQ/Redis, the service uploads the Excel buffer to Cloudflare R2 under a temporary prefix and passes only the object key through the queue. The WhatsApp worker downloads the object, forwards it to GoWA, and best-effort deletes it on success.</p><p>The lifecycle rule described below is the <strong>authoritative cleanup path</strong> for the unhappy case — jobs that fail, phones skipped as local-format, or any other path where the post-send delete never runs. Without this rule, orphaned objects accumulate indefinitely.</p><ul><li><strong>Prefix written by the app:</strong> <code>tmp/wa-manifest/{bookingId}/{uuid}.{xlsx|csv}</code> (extension follows the <code>CUSTOM_BOOKING_ADMIN_MANIFEST_FORMAT</code> env var)</li><li><strong>Code references:</strong><ul><li>Upload: <code>src/modules/custom-booking/custom-booking.service.ts</code> (inside <code>notifyAdminViaWhatsApp</code>)</li><li>Download + best-effort delete: <code>src/modules/queue/processors/whatsapp.processor.ts</code></li></ul></li></ul><h2 id="setting-up-the-rule-cloudflare-dashboard" tabindex="-1">Setting up the rule (Cloudflare Dashboard) <a class="header-anchor" href="#setting-up-the-rule-cloudflare-dashboard" aria-label="Permalink to &quot;Setting up the rule (Cloudflare Dashboard)&quot;">​</a></h2><p>Apply this <strong>per bucket per environment</strong> (dev, staging, production).</p><ol><li><p>Log in to the Cloudflare dashboard and open the account that owns the R2 bucket the application is using.</p></li><li><p>Navigate to <strong>R2</strong> → select the bucket.</p></li><li><p>Open the <strong>Settings</strong> tab.</p></li><li><p>Scroll to <strong>Object lifecycle rules</strong> → click <strong>Add rule</strong>.</p></li><li><p>Fill in the form:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Rule name</td><td><code>expire-tmp-wa-manifest</code></td></tr><tr><td>Prefix</td><td><code>tmp/wa-manifest/</code></td></tr><tr><td>Action</td><td><em>Delete uploaded objects</em></td></tr><tr><td>Age</td><td><code>1 day</code> (or <code>2 days</code> if you want extra buffer)</td></tr></tbody></table><p>Optional (recommended for hygiene, no functional impact here): enable <em>Abort incomplete multipart uploads</em> at <code>1 day</code>. Our manifest uploads are small and single-part, so this will normally be a no-op, but it protects the bucket from unrelated junk accumulating under the same prefix.</p></li><li><p>Click <strong>Save</strong>.</p></li></ol><p>The rule is live immediately. R2 evaluates lifecycle rules roughly once per day, so expect objects to linger up to ~24 hours past the age threshold before deletion — acceptable for this use case.</p><h2 id="important-details" tabindex="-1">Important details <a class="header-anchor" href="#important-details" aria-label="Permalink to &quot;Important details&quot;">​</a></h2><ul><li><strong>Trailing slash matters.</strong> The prefix must be <code>tmp/wa-manifest/</code> (with slash). <code>tmp/wa-manifest</code> (no slash) would match unintended sibling keys; <code>/tmp/wa-manifest/</code> (leading slash) would match nothing, because the app never writes a leading slash.</li><li><strong>Minimum age is 1 day.</strong> R2 does not support sub-day expiration via lifecycle rules. This is why the post-send delete exists in the worker — it handles the common case within seconds, and this rule handles the exceptions.</li><li><strong>Other rules are preserved.</strong> Adding a rule through the dashboard does not replace existing rules on the bucket. (This is different from the S3 API&#39;s <code>PutBucketLifecycleConfiguration</code>, which replaces the whole ruleset.)</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>After saving:</p><ol><li>Upload a probe object manually (via the dashboard or any S3 client) at <code>tmp/wa-manifest/__probe/probe.txt</code>.</li><li>Note the upload timestamp.</li><li>Return within 24–48 hours and confirm the object is gone.</li></ol><p>Alternatively, trigger a real admin notification and confirm that:</p><ul><li>The object appears under <code>tmp/wa-manifest/{bookingId}/</code> briefly.</li><li>It disappears after the worker sends (immediate, via the best-effort delete).</li><li>For a deliberately failing case (e.g. phone misconfigured so the worker never sends), the object disappears within ~24–48 hours via the lifecycle rule.</li></ul><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>To remove the rule, return to <strong>R2</strong> → bucket → <strong>Settings</strong> → <strong>Object lifecycle rules</strong> and delete the entry named <code>expire-tmp-wa-manifest</code>. No data loss — existing objects remain in place; the rule only governs future expirations.</p>',18)])])}const m=t(r,[["render",l]]);export{u as __pageData,m as default};
